/* QadamX v5 workspace: template forms, AI draft with citations, editing timer, version diff,
 * mentor rubric and progress, team profiles with photos, administration and evaluation pages. */
'use strict';
Object.assign(state,{form:null,qtab:'form',profiles:[],metrics:null,metricsBusy:false,aiStatus:null,aiBusy:false,rubric:{},adminAccounts:[],audit:[],leads:[],auditFilter:'',diffA:null,diffB:null,profileDraft:null,newPassword:'',timer:{sourceId:null,pending:0,activity:Date.now()}});
const TT=(ru,kk)=>t(ru,kk);
state.profileDirty=false;state.profilePhotoBusy=false;state.accountDraft={};state.menuOpen=false;
function hasUnsavedForms(){return state.profileDirty||Object.values(state.accountDraft).some(v=>String(v).trim());}
const baseHasUnsaved=hasUnsaved;
hasUnsaved=function(){return baseHasUnsaved()||hasUnsavedForms()||state.profilePhotoBusy;};
const baseCheckpoint=checkpoint;
checkpoint=async function(options={}){
 if(state.profilePhotoBusy){toast(TT('Дождитесь обработки фото.','Фото өңделгенше күтіңіз.'));return false;}
 if(!await baseCheckpoint(options))return false;
 if(options.leaving&&hasUnsavedForms()){
  if(!window.confirm(TT('Изменения формы не сохранены. Покинуть страницу и удалить их?','Нысандағы өзгерістер сақталмады. Беттен шығып, оларды жою керек пе?')))return false;
  state.profileDraft=null;state.profileDirty=false;state.accountDraft={};state.newPassword='';
 }
 return true;
};
// ACI-BENCH: "[doctor] text"; MTS-Dialog: "Doctor: text".
const SPEAKER_RE=/^\s*(?:\[([a-z_ ]+)\]|([A-Za-z_ ]{2,30}):)\s*/i;
Object.assign(paths,{users:'M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M2 21v-1a6 6 0 0 1 12 0v1 M17 11a3 3 0 1 0 0-6 M22 21v-1a5 5 0 0 0-4-5',audit:'M4 4h16v16H4z M8 9h8 M8 13h8 M8 17h5',leads:'M3 11l18-8-8 18-2-8z',team:'M8 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M16 11a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M2 20a6 6 0 0 1 12 0 M10 20a6 6 0 0 1 12 0',profile:'M12 12a5 5 0 1 0 0-10 5 5 0 0 0 0 10 M3 22a9 9 0 0 1 18 0',progress:'M3 20h18 M5 16l5-6 4 3 6-8',evaluation:'M4 20V4h16v16z M8 15l3-4 3 2 3-5',notifications:'M6 8a6 6 0 1 1 12 0c0 7 3 8 3 8H3s3-1 3-8 M10 21h4',assignments:'M16 21v-2a4 4 0 0 0-8 0v2 M12 11a4 4 0 1 0 0-8 M19 8v6 M22 11h-6',integrations:'M12 2v6 M8 6h8 M5 12a7 7 0 0 0 14 0 M12 19v3',requests:'M3 5h18v14H3z M3 6l9 7 9-7'});
const extraNames={users:['Учётные записи','Есептік жазбалар'],audit:['Журнал действий','Әрекеттер журналы'],leads:['Заявки на пилот','Пилотқа өтінімдер'],team:['Наставники и врачи','Тәлімгерлер мен дәрігерлер'],profile:['Мой профиль','Менің профилім'],progress:['Прогресс','Үлгерім'],evaluation:['Оценка качества','Сапаны бағалау'],analytics:['Время оформления','Рәсімдеу уақыты']};
function pageLabel(n){if(extraNames[n])return TT(...extraNames[n]);if(n==='home'&&state.role==='admin')return TT('Обзор','Шолу');return label(n);}
// ---------- shared helpers ----------
const safeRole=r=>roleNames[r]?roleLabel(r):'';
const fmtMs=ms=>{const s=Math.round((ms||0)/1000),m=Math.floor(s/60);return m>=60?`${Math.floor(m/60)} ${TT('ч','сағ')} ${m%60} мин`:`${m}:${String(s%60).padStart(2,'0')}`;};
const median=a=>{if(!a.length)return 0;const s=[...a].sort((x,y)=>x-y),m=Math.floor(s.length/2);return s.length%2?s[m]:(s[m-1]+s[m])/2;};
function profileOf(login){return state.profiles.find(p=>p.login===login)||{login,name:login,role:'',title:'',specialty:'',bio:'',photo:''};}
function avatarSrc(p){return p.photo||QAvatars.url(p.login||p.name||'x');}
function avatar(p,size=40){return `<img class="q-avatar" src="${esc(avatarSrc(p))}" alt="" width="${size}" height="${size}" style="width:${size}px;height:${size}px">`;}
function displayName(login){const p=profileOf(login);return p.name||login;}
async function quiet(path){try{return await api(path)}catch{return null}}
async function loadProfiles(){const r=await quiet('/api/profiles');if(r?.profiles)state.profiles=r.profiles;}
// One request at a time: callers share the in-flight promise. A page that needs metrics asks
// for them once and re-renders once (never from inside render), so a slow or failed request
// cannot spin the page into a render → load → render loop.
function loadMetrics(){if(state.metricsPromise)return state.metricsPromise;state.metricsError=false;state.metricsPromise=(async()=>{try{const r=await quiet('/api/metrics');if(r?.documents)state.metrics=r.documents;else state.metricsError=true;}finally{state.metricsPromise=null;}})();return state.metricsPromise;}
function needMetrics(page){if(state.metrics||state.metricsPromise||state.metricsError)return;loadMetrics().then(()=>{if(state.page===page&&!hasUnsaved())render();});}
function metricsPending(page){return heading(pageLabel(page),state.metricsError?TT('Не удалось загрузить данные.','Деректерді жүктеу мүмкін болмады.'):TT('Загрузка…','Жүктелуде…'))+(state.metricsError?`<button data-q="metrics-retry">${TT('Повторить','Қайталау')}</button>`:`<div class="card skeleton"></div>`);}
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(b?.dataset.q==='metrics-retry'){state.metricsError=false;needMetrics(state.page);render();}});
async function loadAiStatus(){const r=await quiet('/api/ai/status');state.aiStatus=r?{available:!!r.available,model:r.model}:{available:false,error:true};}
function aiConnectionLabel(){return !state.aiStatus?'Проверяем подключение…':state.aiStatus.error?'Не удалось проверить подключение':state.aiStatus.available?'Настроено':'Не подключено';}
const SCORE_KEYS=[['accuracy','Точность фактов','Фактілердің дәлдігі'],['completeness','Полнота','Толықтығы'],['structure','Структура','Құрылымы'],['terminology','Терминология','Терминология'],['grounding','Опора на источник','Дереккөзге сүйену']];
const avgScore=s=>{const v=Object.values(s||{}).filter(Number.isInteger);return v.length?v.reduce((a,b)=>a+b,0)/v.length:null;};
// ---------- word diff ----------
function diffWords(a,b){
 const A=String(a||'').split(/(\s+)/).filter(x=>x!==''),B=String(b||'').split(/(\s+)/).filter(x=>x!=='');
 if(A.length*B.length>4e6)return [{t:'del',v:a},{t:'ins',v:b}];
 const n=A.length,m=B.length,dp=Array.from({length:n+1},()=>new Uint16Array(m+1));
 for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=A[i]===B[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);
 const out=[];let i=0,j=0;const push=(t,v)=>{const l=out[out.length-1];if(l&&l.t===t)l.v+=v;else out.push({t,v});};
 while(i<n&&j<m){if(A[i]===B[j]){push('eq',A[i]);i++;j++;}else if(dp[i+1][j]>=dp[i][j+1]){push('del',A[i++]);}else push('ins',B[j++]);}
 while(i<n)push('del',A[i++]);while(j<m)push('ins',B[j++]);return out;
}
function diffMarkup(a,b){const parts=diffWords(a,b),ins=parts.filter(p=>p.t==='ins'&&p.v.trim()).reduce((s,p)=>s+p.v.trim().split(/\s+/).length,0),del=parts.filter(p=>p.t==='del'&&p.v.trim()).reduce((s,p)=>s+p.v.trim().split(/\s+/).length,0);
 return `<div class="diff-stats"><span class="badge green">+${ins} ${TT('слов','сөз')}</span><span class="badge red">−${del} ${TT('слов','сөз')}</span></div><div class="diff-view">${parts.map(p=>p.t==='eq'?esc(p.v):p.t==='ins'?`<ins>${esc(p.v)}</ins>`:`<del>${esc(p.v)}</del>`).join('')}</div>`;}
// ---------- form state ----------
function initForm(force=false){
 const d=documentFor(),sid=state.selected;
 if(!force&&state.form&&state.form.sourceId===sid&&(state.form.dirty||state.form.rev===(d?.revision||0)))return state.form;
 let template=d?.template||'',values={...(d?.fields||{})};
 if(!d){template=state.form?.pendingTemplate&&state.form.sourceId===sid?state.form.pendingTemplate:(state.role==='student'?'soap':'consult');values=QTemplates.defaults(template,{cardNo:'QX-'+String(DATA.findIndex(r=>r.id===sid)+1).padStart(4,'0')});}
 else if(!Object.hasOwn(QTemplates.list,template))template='free';
 state.form={sourceId:sid,template,values,dirty:false,rev:d?.revision||0,focus:null,free:template==='free'?(d?.text||''):''};
 return state.form;
}
function formText(){const f=state.form;return f.template==='free'?(f.free||'').trim():QTemplates.toText(f.template,f.values,state.lang);}
function formChanged(){const f=state.form,d=documentFor();if(!f||f.sourceId!==state.selected)return false;if(!d)return f.template==='free'?!!f.free.trim():Object.entries(f.values).some(([k,v])=>!['visit_date','card_no','period_to'].includes(k)&&!k.endsWith('__src')&&String(v).trim());return f.dirty;}
hasUnsavedDraft=function(){return state.page==='editor'&&!!state.form&&formChanged()&&!['review','approved'].includes(documentFor()?.status);};
saveDraft=async function(){
 if(!state.serverReady){toast(t('Дождитесь загрузки данных с сервера.'));return false}if(!QCore.canEdit(state.role))return false;
 const f=state.form,sourceId=state.selected,old=documentFor();if(!f||f.sourceId!==sourceId)return true;if(old&&['review','approved'].includes(old.status))return false;
 const text=formText();if(!text){toast(TT('Заполните хотя бы одно поле документа.','Құжаттың кемінде бір өрісін толтырыңыз.'));return false}
 const activeMs=state.timer.sourceId===sourceId?Math.round(state.timer.pending):0,snapshot=JSON.stringify(f.values)+f.free;
 const ok=await operation(async()=>{const body={id:old?.id,sourceId,text,expectedRevision:old?.revision,activeMs};if(f.template!=='free'){body.template=f.template;body.fields=f.values;}const result=await api('/api/documents',body);state.docs[sourceId]={...mappedDoc(result.document),versions:old?.versions||[]};});
 if(!ok)return false;if(state.timer.sourceId===sourceId)state.timer.pending=Math.max(0,state.timer.pending-activeMs);
 if(state.form?.sourceId===sourceId){state.form.rev=state.docs[sourceId].revision;state.form.dirty=JSON.stringify(state.form.values)+state.form.free!==snapshot;}
 toast(TT('Документ сохранён на сервере.','Құжат серверде сақталды.'));return true;
};
changeDocument=async function(action,comment='',checks=[]){const sourceId=state.selected,d=documentFor();if(!d)return;const activeMs=state.timer.sourceId===sourceId&&d.owner===SESSION.login?Math.round(state.timer.pending):0;
 return operation(async()=>{const result=await api('/api/documents/'+encodeURIComponent(d.id)+'/action',{action,expectedRevision:d.revision,comment,checks,activeMs});state.docs[sourceId]={...mappedDoc(result.document),versions:d.versions||[]};if(activeMs)state.timer.pending=Math.max(0,state.timer.pending-activeMs);state.checks=[false,false,false];state.doctorReviewComment='';state.form=null;await syncServer(false);try{await loadDocumentHistory(sourceId)}catch{}render();toast(t('Изменение сохранено. Уведомления доставлены в кабинеты.'));});};
const baseMapped=mappedDoc;mappedDoc=function(d){return {...baseMapped(d),fields:d.fields||{},template:d.template||'',scores:d.scores||{},activeMs:d.activeMs||0,approvedAt:d.approvedAt||null};};
// ---------- timer ----------
setInterval(()=>{const tm=state.timer,d=documentFor();if(state.page!=='editor'||!QCore.canEdit(state.role)||d&&['review','approved'].includes(d.status)){return;}
 if(tm.sourceId!==state.selected){tm.sourceId=state.selected;tm.pending=0;}
 const visible=typeof document.visibilityState==='undefined'||document.visibilityState==='visible';if(visible&&Date.now()-tm.activity<90000)tm.pending+=1000;
 const el=document.getElementById?.('q-timer');if(el)el.textContent=fmtMs((d?.activeMs||0)+tm.pending);},1000);
['input','keydown','pointerdown','scroll'].forEach(ev=>document.addEventListener(ev,()=>{state.timer.activity=Date.now();},{passive:true,capture:true}));
// ---------- editor ----------
function fieldInput(f,v,locked){const id='qf-'+f.key,common=`id="${id}" data-field="${f.key}" ${locked?'disabled':''}`,ph=f.placeholder?` placeholder="${esc(QTemplates.lab(f.placeholder,state.lang))}"`:'';
 if(f.type==='area')return `<textarea ${common} rows="${f.rows||3}"${ph}>${esc(v[f.key]||'')}</textarea>`;
 if(f.type==='select')return `<select ${common}>${f.options.map(([val,l])=>`<option value="${esc(val)}" ${v[f.key]===val?'selected':''}>${esc(QTemplates.lab(l,state.lang))}</option>`).join('')}</select>`;
 if(f.type==='vitals')return `<div class="vitals">${f.parts.map(([k,l,p])=>`<label class="vital"><span>${esc(l)}</span><input data-field="vitals_${k}" value="${esc(v['vitals_'+k]||'')}" placeholder="${esc(p)}" ${locked?'disabled':''} inputmode="decimal"></label>`).join('')}</div>`;
 return `<input ${common} type="${f.type==='date'?'date':'text'}" value="${esc(v[f.key]||'')}"${ph}>`;}
function citeChips(key){const count=selected().dialogue.split(/\n+/).filter(Boolean).length;const src=[...new Set(String(state.form.values[key+'__src']||'').split(',').filter(n=>/^[1-9]\d*$/.test(n)&&Number(n)<=count).map(Number))];return src.length?`<div class="cite-row"><span>${TT('Источник','Дереккөз')}:</span>${src.map(n=>`<button type="button" class="cite" data-cite="${n}">${n}</button>`).join('')}</div>`:'';}
function formMarkup(locked){const f=state.form,tpl=QTemplates.list[f.template];
 const pat=tpl.fields.filter(x=>x.patient),rest=tpl.fields.filter(x=>!x.patient),prog=QTemplates.filled(f.template,f.values);
 const cell=x=>`<div class="ff ${x.half?'half':x.quarter?'quarter':x.wide3?'wide3':'full'}" data-wrap="${x.key}"><label for="qf-${x.key}">${esc(QTemplates.lab(x.label,state.lang))}</label>${x.hint?`<small class="ff-hint">${esc(QTemplates.lab(x.hint,state.lang))}</small>`:''}${fieldInput(x,f.values,locked)}${citeChips(x.key)}</div>`;
 return `<div class="form-progress"><div><strong>${esc(QTemplates.lab(tpl.name,state.lang))}</strong><small id="q-progress">${prog.done} / ${prog.total} ${TT('разделов заполнено','бөлім толтырылды')}</small></div><div class="progress"><div id="q-progress-bar" style="width:${prog.total?prog.done/prog.total*100:0}%"></div></div></div>
 <fieldset class="form-block"><legend>${TT('Пациент','Пациент')}<span class="badge amber">${TT('только учебные данные','тек оқу деректері')}</span></legend><div class="form-cells">${pat.map(cell).join('')}</div></fieldset>
 <fieldset class="form-block"><legend>${TT('Содержание документа','Құжат мазмұны')}</legend><div class="form-cells">${rest.map(cell).join('')}</div></fieldset>`;}
function templatePicker(){return `<div class="tpl-grid">${QTemplates.order.map(id=>{const x=QTemplates.list[id];return `<button type="button" class="tpl-card ${state.form.template===id?'active':''}" data-template="${id}"><span class="tpl-icon">${x.icon}</span><strong>${esc(QTemplates.lab(x.name,state.lang))}</strong><small>${esc(QTemplates.lab(x.description,state.lang))}</small></button>`;}).join('')}</div>`;}
function docContext(d){const me=profileOf(d?.owner||SESSION.login);return {lang:state.lang,doctor:me.name||SESSION.name||SESSION.login,specialty:me.specialty||me.title||'',number:d?('QX-'+d.id.slice(0,8).toUpperCase()):TT('черновик','жоба'),status:d?.status,approvedAt:d?.approvedAt?dateText(d.approvedAt):'',caseId:selected().originalId};}
function aiButton(locked){if(locked||state.form.template==='free')return '';const st=state.aiStatus;return `<button type="button" class="ai-button" data-q="ai" ${state.aiBusy?'disabled':''} title="${st?.available?esc(st.model||''):TT('Нужен серверный ключ ANTHROPIC_API_KEY','ANTHROPIC_API_KEY серверлік кілті қажет')}">✦ ${state.aiBusy?TT('AI готовит черновик…','AI жоба дайындап жатыр…'):TT('AI-черновик по диалогу','Диалог бойынша AI-жоба')}</button>${st&&!st.available?`<span class="badge amber">${TT('AI не подключён','AI қосылмаған')}</span>`:''}`;}
editor=function(){const r=selected(),d=documentFor(),locked=!!d&&['approved','review'].includes(d.status);const f=initForm();
 const lines=r.dialogue.split(/\n+/).filter(Boolean),used=new Set(Object.entries(f.values).filter(([k])=>k.endsWith('__src')).flatMap(([,v])=>String(v).split(',')).filter(Boolean).map(Number));
 const tabs=[['form',TT('Форма','Нысан')],['doc',TT('Документ','Құжат')],['reference',TT('Эталон','Эталон')],['history',TT('История и изменения','Тарих және өзгерістер')]];
 const qtab=tabs.some(([id])=>id===state.qtab)?state.qtab:'form';
 let panel='';
 if(qtab==='form'){
  panel=(!d&&!locked?`<div class="pick-head"><h3>${TT('Шаблон документа','Құжат үлгісі')}</h3><small>${TT('Выберите форму — поля, дата и номер карты подставятся сами.','Нысанды таңдаңыз — өрістер, күн және карта нөмірі өзі қойылады.')}</small></div>${templatePicker()}`:'')+
  `<div class="ai-row">${aiButton(locked)}<span class="muted small">${TT('Нажмите на номер фрагмента слева, чтобы вставить дословную цитату в выбранное поле.','Таңдалған өріске сөзбе-сөз дәйексөз қою үшін сол жақтағы фрагмент нөмірін басыңыз.')}</span></div>`+
  (f.template==='free'?`<div class="notice warm">${TT('Запись создана до появления шаблонов. Можно продолжить свободным текстом.','Жазба үлгілер пайда болғанға дейін жасалған. Еркін мәтінмен жалғастыруға болады.')}</div><textarea id="q-free" class="editor-text" ${locked?'readonly':''}>${esc(f.free)}</textarea>`:formMarkup(locked));
 }
 if(qtab==='doc')panel=`<div class="doc-preview">${f.template==='free'?`<pre class="reference">${esc(formText())}</pre>`:QTemplates.printHtml(f.template,f.values,docContext(d))}</div>`;
 if(qtab==='reference')panel=`<div class="notice warm">${t('Эталон авторов датасета, не результат QadamX. Не используйте его как вход модели при оценке.')}</div><pre class="reference" style="margin-top:15px">${esc(r.reference)}</pre>`;
 if(qtab==='history'){const vs=(d?.versions||[]).slice().sort((a,b)=>b.revision-a.revision);
  if(vs.length<1)panel=empty(t('Версий ещё нет'),t('Сохраните первый черновик.'));
  else{const B=vs.find(v=>v.revision===state.diffB)||vs[0],A=vs.find(v=>v.revision===state.diffA)||vs.find(v=>v.revision<B.revision&&v.text!==B.text)||vs[1]||vs[0];
   const opt=(sel,id)=>`<select data-diff="${id}">${vs.map(v=>`<option value="${v.revision}" ${v.revision===sel.revision?'selected':''}>${TT('Версия','Нұсқа')} ${v.revision} · ${esc(dateText(v.at||v.createdAt))} · ${esc(displayName(v.actor||''))}</option>`).join('')}</select>`;
   panel=`<div class="diff-pick"><label>${TT('Было','Бұрын')}${opt(A,'a')}</label><label>${TT('Стало','Қазір')}${opt(B,'b')}</label></div>${A===B?`<pre class="reference">${esc(B.text)}</pre>`:diffMarkup(A.text,B.text)}<div class="version-list">${vs.map(v=>`<div class="row"><span class="num-icon">${v.revision}</span><div class="grow"><strong>${esc(displayName(v.actor||''))}</strong><small>${esc(dateText(v.at||v.createdAt))}${v.activeMs?' · ⏱ '+fmtMs(v.activeMs):''}</small>${v.comment?`<p class="wrap-text muted">${esc(v.comment)}</p>`:''}</div>${badge(v.status)}${avgScore(v.scores)?`<span class="badge blue">★ ${avgScore(v.scores).toFixed(1)}</span>`:''}</div>`).join('')}</div>`;}}
 const status=d?.status||'draft';
 const actions=`<div class="editor-actions">${!locked?`<button class="primary" data-q="save">${TT('Сохранить','Сақтау')}</button>`:''}${(!d||['draft','returned'].includes(status))?`<button data-q-status="submit" ${!d?'disabled':''}>${t(state.role==='student'?'Отправить наставнику':'Перейти к финальной проверке')} →</button>`:''}${state.role==='student'&&status==='review'?`<button data-action="recall-study">${t('Отозвать на доработку','Өңдеу үшін кері қайтарып алу')}</button>`:''}${status==='approved'&&state.role==='doctor'?`<button data-q-status="revise">${t('Создать новую редакцию')}</button>`:''}<span class="spacer"></span><button data-q="print" title="${TT('Откроется окно печати — выберите «Сохранить как PDF»','Басып шығару терезесі ашылады — «PDF ретінде сақтау» таңдаңыз')}">⎙ PDF</button><button data-q="word">W Word</button><button data-q="txt">.txt</button></div>`;
 const review=d?.status==='review'&&state.role==='doctor'?`<div class="review-box"><h3>${TT('Финальная проверка','Соңғы тексеру')}</h3><div class="checks">${[t('Идентификатор случая проверен'),t('Текст сопоставлен с источником'),t('Числа, отрицания и принадлежность сведений проверены')].map((l,i)=>`<label><input type="checkbox" data-check="${i}" ${state.checks[i]?'checked':''}>${l}</label>`).join('')}</div><label for="review-comment">${t('Комментарий наставника / врача')}</label><textarea id="review-comment" rows="2">${esc(state.doctorReviewComment||'')}</textarea><div class="actions"><button class="primary" data-q-status="approve">${t('Утвердить в демо')}</button><button data-q-status="return">${t('Вернуть с комментарием')}</button></div></div>`:'';
 return heading(`${t(state.role==='student'?'Учебная запись':'Приём')} ${esc(r.originalId)}`,TT('Заполните форму — документ соберётся автоматически и будет готов к печати.','Нысанды толтырыңыз — құжат автоматты түрде жиналып, басып шығаруға дайын болады.'),`<button data-go="${state.role==='student'?'practice':'library'}">← ${TT('Назад','Артқа')}</button>`)+
 `<div class="research-strip"><span class="badge">${esc(r.dataset)}</span><span class="badge amber">${t('Синтетический случай')}</span>${badge(status)}<span class="badge">${TT('Версия','Нұсқа')} ${d?.revision||0}</span><span class="timer-chip" title="${TT('Активное время работы над документом. Пауза после 90 секунд без действий.','Құжатпен белсенді жұмыс уақыты. 90 секунд әрекетсіз болса тоқтайды.')}">⏱ <span id="q-timer">${fmtMs((d?.activeMs||0)+(state.timer.sourceId===state.selected?state.timer.pending:0))}</span></span></div>
 <div class="editor-grid q-editor"><section class="card editor-panel source-panel"><div class="card-head"><h2>${t('Источник')}</h2><span class="badge">${lines.length} ${t('фрагментов')}</span></div><div class="transcript">${lines.map((line,i)=>{const m=SPEAKER_RE.exec(line);const who=m?(m[1]||m[2]).toLowerCase().trim():'';m&&(m[2]=line.slice(m[0].length));return `<div class="utterance ${who==='doctor'?'u-doc':who==='patient'?'u-pat':''} ${used.has(i+1)?'source-on':''}" id="fragment-${i+1}"><div class="u-head"><button type="button" class="frag-num" data-frag="${i+1}" ${locked?'disabled':''} title="${TT('Вставить цитату в поле','Дәйексөзді өріске қою')}">${i+1}</button><strong>${esc(who==='doctor'?TT('Врач','Дәрігер'):who==='patient'?TT('Пациент','Пациент'):who||t('Фрагмент'))}</strong></div><span lang="en">${esc(m?line.slice(m[0].length):line)}</span></div>`;}).join('')}</div><p class="footer-note">${esc(r.source)} · ${t('Текст сохранён без перевода и изменений.')}</p></section>
 <section class="card editor-panel"><div class="tabs">${tabs.map(([id,l])=>`<button data-q-tab="${id}" class="${qtab===id?'active':''}">${l}</button>`).join('')}</div>${panel}${actions}${review}${d?.comment?`<div class="notice section-gap"><strong>${TT('Комментарий','Пікір')}:</strong> ${esc(d.comment)}</div>`:''}<p class="footer-note">${t('Утверждение в демо не является ЭЦП. Экспорт не является действительным медицинским документом.')}</p></section></div>`;
};
function updateProgress(){const f=state.form;if(!f||f.template==='free')return;const p=QTemplates.filled(f.template,f.values),el=document.getElementById?.('q-progress'),bar=document.getElementById?.('q-progress-bar');if(el)el.textContent=`${p.done} / ${p.total} ${TT('разделов заполнено','бөлім толтырылды')}`;if(bar)bar.style.width=(p.total?p.done/p.total*100:0)+'%';}
document.addEventListener('input',e=>{const k=e.target.dataset?.field;if(k&&state.form){state.form.values[k]=e.target.value;state.form.dirty=true;updateProgress();}if(e.target.id==='q-free'&&state.form){state.form.free=e.target.value;state.form.dirty=true;}});
document.addEventListener('change',e=>{const k=e.target.dataset?.field;if(k&&state.form&&e.target.tagName==='SELECT'){state.form.values[k]=e.target.value;state.form.dirty=true;}if(e.target.dataset?.diff){state['diff'+e.target.dataset.diff.toUpperCase()]=Number(e.target.value);render();}});
document.addEventListener('focusin',e=>{const k=e.target.dataset?.field;if(k&&state.form)state.form.focus=k;});
function exportCtx(){const d=documentFor();initForm();return {d,ctx:docContext(d),file:'QadamX-'+selected().originalId+'-'+(state.form.template||'doc')};}
function printDocument(html){let root=document.getElementById('print-root');if(!root){root=document.createElement('div');root.id='print-root';document.body.append(root);}root.innerHTML=`<style>${QTemplates.PRINT_CSS}@media print{body.printing>*:not(#print-root){display:none!important}body.printing #print-root{display:block!important}}</style>`+html;document.body.classList.add('printing');const done=()=>{document.body.classList.remove('printing');root.innerHTML='';window.removeEventListener('afterprint',done);};window.addEventListener('afterprint',done);window.print();setTimeout(()=>{if(document.body.classList.contains('printing')&&!matchMedia('print').matches)done();},60000);}
async function runAi(){const f=state.form;if(!f||state.aiBusy)return;if(state.aiStatus&&!state.aiStatus.available){toast(TT('AI ещё не подключён: владелец сайта должен добавить серверный ключ ANTHROPIC_API_KEY. Пока заполняйте форму вручную и цитатами.','AI әлі қосылмаған: сайт иесі ANTHROPIC_API_KEY серверлік кілтін қосуы керек. Әзірге нысанды қолмен және дәйексөздермен толтырыңыз.'));return;}
 const filledKeys=Object.keys(f.values).filter(k=>!k.endsWith('__src')&&String(f.values[k]).trim()&&!['visit_date','card_no','period_to','sex','birth_date','patient_name','urgency'].includes(k));
 if(filledKeys.length&&!window.confirm(TT('AI заполнит только пустые поля. Продолжить?','AI тек бос өрістерді толтырады. Жалғастыру керек пе?')))return;
 state.aiBusy=true;render();
 try{const r=await api('/api/ai/draft',{sourceId:state.selected,template:f.template,fields:QTemplates.aiFields(f.template,state.lang),lines:selected().dialogue.split(/\n+/).filter(Boolean),language:state.lang});let n=0;
  for(const [k,v] of Object.entries(r.fields||{})){if(!v.text||String(f.values[k]||'').trim())continue;f.values[k]=v.text;if(v.fragments?.length)f.values[k+'__src']=v.fragments.join(',');n++;}
  f.dirty=true;toast(TT(`AI заполнил ${n} полей. Проверьте каждое по цитатам источника.`,`AI ${n} өрісті толтырды. Әрқайсысын дереккөз дәйексөздері бойынша тексеріңіз.`));}
 catch(e){toast(e.message)}finally{state.aiBusy=false;render();}}
document.addEventListener('click',async e=>{const b=e.target.closest?.('button');if(!b)return;
 if(b.dataset.qTab){if(b.dataset.qTab==='history'&&documentFor()){try{await loadDocumentHistory()}catch(err){toast(err.message)}}state.qtab=b.dataset.qTab;render();return;}
 if(b.dataset.template&&state.form&&!documentFor()){const cur=state.form.values,next=QTemplates.defaults(b.dataset.template,{cardNo:cur.card_no});for(const k of ['patient_name','birth_date','sex','card_no'])if(cur[k])next[k]=cur[k];state.form={...state.form,template:b.dataset.template,values:next,pendingTemplate:b.dataset.template};render();return;}
 if(b.dataset.cite){const el=document.getElementById('fragment-'+b.dataset.cite);if(el){el.scrollIntoView({behavior:'smooth',block:'center'});el.classList.add('flash');setTimeout(()=>el.classList.remove('flash'),1600);}return;}
 if(b.dataset.frag&&state.form){const f=state.form,i=Number(b.dataset.frag),raw=selected().dialogue.split(/\n+/).filter(Boolean)[i-1]||'';if(f.template==='free'){f.free+=(f.free?'\n\n':'')+`[${t('Цитата источника')} ${i}] ${raw}`;f.dirty=true;render();return;}
  const area=QTemplates.fieldList(f.template).filter(x=>x.type==='area');const key=f.focus&&area.some(x=>x.key===f.focus)?f.focus:area[0].key;
  f.values[key]=(f.values[key]?f.values[key]+'\n':'')+`«${raw.replace(SPEAKER_RE,'')}»`;const src=new Set((f.values[key+'__src']||'').split(',').filter(Boolean));src.add(String(i));f.values[key+'__src']=[...src].sort((a,b)=>a-b).join(',');f.dirty=true;f.focus=key;state.qtab='form';render();document.getElementById('qf-'+key)?.focus();toast(TT('Цитата добавлена в поле «','Дәйексөз «')+QTemplates.lab(QTemplates.fieldList(f.template).find(x=>x.key===key).label,state.lang)+TT('». Переформулируйте её как запись врача.','» өрісіне қосылды. Оны дәрігер жазбасы ретінде қайта тұжырымдаңыз.'));return;}
 const q=b.dataset.q;
 if(q==='save'){if(await saveDraft())render();return;}
 if(q==='ai'){await runAi();return;}
 if(q==='print'||q==='word'||q==='txt'){const {d,ctx,file}=exportCtx();const f=state.form;
  if(q==='txt')download(file+'.txt','QadamX MedTech — '+TT('УЧЕБНЫЙ ДОКУМЕНТ, НЕ ЯВЛЯЕТСЯ МЕДИЦИНСКИМ','ОҚУ ҚҰЖАТЫ, МЕДИЦИНАЛЫҚ ЕМЕС')+'\n\n'+formText());
  else if(f.template==='free'){download(file+'.txt',formText());}
  else if(q==='word')download(file+'.doc',QTemplates.wordFile(f.template,f.values,ctx),'application/msword');
  else printDocument(QTemplates.printHtml(f.template,f.values,ctx));
  return;}
 if(b.dataset.qStatus){const action=b.dataset.qStatus;if(!await checkpoint())return;await changeDocument(action,action==='approve'||action==='return'?(document.getElementById('review-comment')?.value.trim()||''):'',state.checks);return;}
});
// ---------- mentor review with rubric ----------
mentorReview=function(){const r=state.reviews[state.reviewId];if(!r)return empty(t('Работа не выбрана'),t('Откройте работу из очереди проверки.'));const source=DATA.find(x=>x.id===r.sourceId),open=r.status==='review',stu=profileOf(r.student);
 const docView=r.template&&QTemplates.list[r.template]?QTemplates.printHtml(r.template,r.fields||{},{lang:state.lang,doctor:stu.name,specialty:TT('студент','студент'),number:'QX-'+r.id.slice(0,8).toUpperCase(),status:r.status,caseId:source.originalId}):`<pre class="reference">${esc(r.text)}</pre>`;
 const scores=open?state.rubric:(r.scores||{});
 return heading(t('Проверка учебной работы'),`${esc(stu.name)} · ${esc(source.originalId)} · ${t('Версия')} ${r.version}${r.activeMs?' · ⏱ '+fmtMs(r.activeMs):''}`,`<button data-go="practice">← ${t('Все работы')}</button>`)+
 `<div class="editor-grid"><section class="card"><h2>${t('Исходный диалог')}</h2><p class="footer-note">${t('Исходный текст на английском. Перевод интерфейса его не изменяет.')}</p><pre lang="en" class="reference review-source">${esc(source.dialogue)}</pre></section><section class="card"><div class="card-head"><div class="inline">${avatar(stu,42)}<div><h2>${t('Работа студента')}</h2><small>${esc(stu.name)}</small></div></div>${badge(r.status)}</div><div class="doc-preview compact">${docView}</div>
 <div class="rubric section-gap"><h3>${TT('Оценка по критериям','Критерийлер бойынша бағалау')} <small class="muted">1 — ${TT('слабо','әлсіз')}, 5 — ${TT('отлично','өте жақсы')}</small></h3>${SCORE_KEYS.map(([k,ru,kk])=>`<div class="rubric-row"><span>${TT(ru,kk)}</span><div class="seg">${[1,2,3,4,5].map(n=>`<button type="button" data-score="${k}" data-value="${n}" class="${scores[k]===n?'on':''}" ${open?'':'disabled'} aria-pressed="${scores[k]===n}">${n}</button>`).join('')}</div></div>`).join('')}${avgScore(scores)?`<p class="rubric-avg">${TT('Средний балл','Орташа балл')}: <strong>${avgScore(scores).toFixed(1)}</strong></p>`:''}</div>
 <div class="checks">${['Содержание соответствует диалогу','Числа и отрицания переданы точно','Выводы опираются на источник'].map((s,i)=>`<label><input type="checkbox" data-mentor-check="${i}" ${state.mentorChecks[i]?'checked':''} ${open?'':'disabled'}>${t(s)}</label>`).join('')}</div><label for="mentor-comment" style="margin-top:12px">${t('Комментарий студенту')}</label><textarea id="mentor-comment" maxlength="5000" rows="4" ${open?'':'readonly'}>${esc(state.mentorComment||r.comment||'')}</textarea>${open?`<div class="actions"><button type="button" data-mentor-verdict="return">${t('Вернуть на доработку')}</button><button type="button" class="primary" data-mentor-verdict="approve">${t('Зачесть работу')}</button></div>`:`<p class="notice section-gap">${t('Отзыв доступен студенту в его кабинете.')}</p>`}<p class="footer-note">${t('Зачёт подтверждает учебную проверку в прототипе, а не выдачу медицинского документа.')}</p></section></div>`;};
document.addEventListener('click',async e=>{const b=e.target.closest?.('button');if(!b||state.role!=='mentor')return;
 if(b.dataset.reviewOpen){state.rubric={};}
 if(b.dataset.score){state.rubric[b.dataset.score]=Number(b.dataset.value);const c=document.getElementById('mentor-comment');if(c)state.mentorComment=c.value;render();return;}
 if(b.dataset.mentorVerdict){const r=state.reviews[state.reviewId];if(!r||r.status!=='review')return;const action=b.dataset.mentorVerdict,comment=state.mentorComment.trim();
  if(!comment){toast(t('Добавьте понятный комментарий студенту.'));return;}if(action==='approve'&&!state.mentorChecks.every(Boolean)){toast(t('Проверьте все три критерия перед зачётом.'));return;}
  if(Object.keys(state.rubric).length<SCORE_KEYS.length){toast(TT('Поставьте баллы по всем пяти критериям.','Барлық бес критерий бойынша балл қойыңыз.'));return;}
  await operation(async()=>{const result=await api('/api/documents/'+encodeURIComponent(r.id)+'/action',{action,expectedRevision:r.revision,comment,checks:state.mentorChecks,scores:state.rubric});state.mentorComment='';state.rubric={};state.reviews[r.id]={...result.document,requestId:r.id,student:r.owner,version:result.document.revision};await syncServer(false);state.metrics=null;render();toast(t('Отзыв сохранён. Студент получил уведомление.'));});}
});
reviewRows=function(rows){return rows.length?rows.map(r=>{const p=profileOf(r.student);return `<div class="row">${avatar(p,42)}<div class="grow"><strong>${esc(p.name)}</strong><p>${esc(DATA.find(x=>x.id===r.sourceId)?.originalId||r.sourceId)}${r.template&&QTemplates.list[r.template]?' · '+esc(QTemplates.lab(QTemplates.list[r.template].short,state.lang)):''}</p><small>${t('Версия')} ${r.version}${r.activeMs?' · ⏱ '+fmtMs(r.activeMs):''}</small></div>${avgScore(r.scores)?`<span class="badge blue">★ ${avgScore(r.scores).toFixed(1)}</span>`:''}${badge(r.status)}<button data-review-open="${esc(r.requestId)}">${t('Проверить')} →</button></div>`;}).join(''):empty(t('Нет работ для проверки'),t('Работы появятся после отправки назначенным вам студентом.'));};
// ---------- charts ----------
function lineChart(points,{max=5,height=180,label=''}={}){if(!points.length)return empty(TT('Пока нет оценок','Әзірге баға жоқ'),TT('График появится после первой проверки наставником.','Тәлімгер алғаш тексергеннен кейін график пайда болады.'));
 const W=560,H=height,px=36,py=18,step=points.length>1?(W-px*2)/(points.length-1):0,y=v=>H-py-(v/max)*(H-py*2),x=i=>px+i*step;
 const path=points.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(p.v).toFixed(1)}`).join(' ');
 return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(label)}">${[1,2,3,4,5].map(v=>`<g><line x1="${px}" x2="${W-px}" y1="${y(v)}" y2="${y(v)}" class="grid"/><text x="${px-10}" y="${y(v)+4}" text-anchor="end">${v}</text></g>`).join('')}<path d="${path} L${x(points.length-1)} ${H-py} L${px} ${H-py}Z" class="area"/><path d="${path}" class="line"/>${points.map((p,i)=>`<g><circle cx="${x(i)}" cy="${y(p.v)}" r="5" class="dot"><title>${esc(p.label)}: ${p.v.toFixed(1)}</title></circle><text x="${x(i)}" y="${H-2}" text-anchor="middle">${esc(p.short||'')}</text></g>`).join('')}</svg>`;}
function barList(items,unit=''){const max=Math.max(1,...items.map(i=>i.v));return `<div class="bars">${items.map(i=>`<div class="bar-row"><span class="bar-label">${esc(i.label)}</span><div class="bar-track"><div class="bar-fill" style="width:${i.v/max*100}%"></div></div><span class="bar-value">${esc(i.text??(i.v.toFixed(1)+unit))}</span></div>`).join('')}</div>`;}
function scorePoints(docs){return docs.flatMap(d=>d.history.filter(h=>avgScore(h.scores)).map(h=>({at:h.at,v:avgScore(h.scores),scores:h.scores,label:(DATA.find(x=>x.id===d.sourceId)?.originalId||'')+' v'+h.revision}))).sort((a,b)=>new Date(a.at)-new Date(b.at)).map((p,i)=>({...p,short:String(i+1)}));}
function criteriaBars(points){if(!points.length)return '';const last=points.slice(-5);return barList(SCORE_KEYS.map(([k,ru,kk])=>{const v=last.map(p=>p.scores[k]).filter(Number.isInteger);return {label:TT(ru,kk),v:v.length?v.reduce((a,b)=>a+b,0)/v.length:0};}),'');}
// ---------- progress page ----------
function progressPage(){if(!state.metrics){needMetrics('progress');return metricsPending('progress');}
 if(state.role==='student'){const pts=scorePoints(state.metrics),docs=state.metrics;
  return heading(TT('Мой прогресс','Менің үлгерімім'),TT('Средний балл наставника по каждой проверенной версии и время работы над записями.','Әр тексерілген нұсқа бойынша тәлімгердің орташа балы және жазбаларға жұмсалған уақыт.'))+statsMarkup([[docs.length,'Учебных записей','Всего'],[docs.filter(d=>d.status==='approved').length,'Зачтено','Учебный результат'],[pts.length?pts[pts.length-1].v.toFixed(1):'—','Последний балл','Из 5'],[docs.length?fmtMs(median(docs.map(d=>d.activeMs).filter(Boolean))):'—','Медиана времени','На одну запись']])+
  `<div class="dashboard-columns"><section class="card"><h2>${TT('Динамика оценок','Бағалар динамикасы')}</h2>${lineChart(pts,{label:TT('Средний балл','Орташа балл')})}</section><section class="card"><h2>${TT('Критерии (последние 5 проверок)','Критерийлер (соңғы 5 тексеру)')}</h2>${criteriaBars(pts)||empty(TT('Нет данных','Дерек жоқ'),'')}</section></div>`;}
 const byStudent={};for(const d of state.metrics)(byStudent[d.owner]??=[]).push(d);
 return heading(TT('Прогресс студентов','Студенттердің үлгерімі'),TT('Оценки по критериям и время работы ваших студентов.','Студенттеріңіздің критерийлер бойынша бағалары және жұмыс уақыты.'))+(Object.keys(byStudent).length?`<div class="student-progress">${Object.entries(byStudent).map(([login,docs])=>{const p=profileOf(login),pts=scorePoints(docs);return `<section class="card"><div class="card-head"><div class="inline">${avatar(p,48)}<div><h2>${esc(p.name)}</h2><small>${docs.length} ${TT('записей','жазба')} · ${docs.filter(d=>d.status==='approved').length} ${TT('зачтено','есептелді')} · ⏱ ${fmtMs(median(docs.map(d=>d.activeMs).filter(Boolean)))}</small></div></div>${pts.length?`<span class="badge blue">★ ${pts[pts.length-1].v.toFixed(1)}</span>`:''}</div>${lineChart(pts,{height:150,label:p.name})}${criteriaBars(pts)}</section>`;}).join('')}</div>`:`<section class="card">${empty(TT('Нет назначенных студентов','Тағайындалған студенттер жоқ'),TT('Врач назначает студентов в своём кабинете.','Дәрігер студенттерді өз кабинетінде тағайындайды.'))}</section>`);}
// ---------- time analytics ----------
