function teamCard(p,highlight){return `<article class="team-card ${highlight?'highlight':''}">${avatar(p,88)}<div class="team-body"><span class="badge ${p.role==='mentor'?'purple':p.role==='doctor'?'green':''}">${esc(safeRole(p.role))}</span>${highlight?`<span class="badge amber">${TT('Ваш наставник','Сіздің тәлімгеріңіз')}</span>`:''}<h3>${esc(p.name)}</h3>${p.title?`<p class="team-title">${esc(p.title)}</p>`:''}${p.specialty?`<p class="muted">${esc(p.specialty)}</p>`:''}${p.bio?`<p class="team-bio">${esc(p.bio)}</p>`:''}${p.role==='mentor'?`<small>${p.students} ${TT('студентов','студент')}</small>`:''}</div></article>`;}
function teamPage(){const mine=state.assignments?.find(a=>a.student===SESSION.login)?.mentor;const staff=state.profiles.filter(p=>['mentor','doctor'].includes(p.role)).sort((a,b)=>(b.login===mine)-(a.login===mine)||a.role.localeCompare(b.role));
 return heading(pageLabel('team'),TT('Кто проверяет учебные работы и ведёт приёмы. Фото и описание каждый заполняет в своём профиле.','Оқу жұмыстарын кім тексереді және қабылдау жүргізеді. Фото мен сипаттаманы әркім өз профилінде толтырады.'),`<button data-go="profile">${TT('Мой профиль','Менің профилім')} →</button>`)+(staff.length?`<div class="team-grid">${staff.map(p=>teamCard(p,p.login===mine)).join('')}</div>`:`<section class="card">${empty(TT('Загрузка профилей…','Профильдер жүктелуде…'),'')}</section>`);}
function profilePage(){const me=profileOf(SESSION.login),d=state.profileDraft||(state.profileDraft={name:me.name||SESSION.name||'',title:me.title,specialty:me.specialty,bio:me.bio,photo:me.photo});
 return heading(pageLabel('profile'),TT('Имя, должность и фото видят коллеги, студенты и посетители главной страницы.','Аты, лауазымы мен фотосын әріптестер, студенттер және басты бет қонақтары көреді.'))+`<div class="grid-two"><form id="profile-form" class="card stack"><div class="profile-photo">${avatar({...me,photo:d.photo},120)}<div class="stack"><label class="file-button">${TT('Загрузить фото','Фото жүктеу')}<input type="file" accept="image/jpeg,image/png,image/webp" data-photo></label>${d.photo?`<button type="button" data-q="photo-remove">${TT('Убрать фото','Фотоны алып тастау')}</button>`:''}<small class="muted">${TT('Фото уменьшается до 320×320 и хранится на сервере. Без фото показывается иллюстрация.','Фото 320×320 өлшемге кішірейтіліп, серверде сақталады. Фото болмаса, иллюстрация көрсетіледі.')}</small></div></div>
 <div class="form-grid"><div><label for="pf-name">${TT('Имя и фамилия','Аты-жөні')}</label><input id="pf-name" data-pf="name" maxlength="120" value="${esc(d.name)}" required></div><div><label for="pf-title">${TT('Должность / степень','Лауазымы / дәрежесі')}</label><input id="pf-title" data-pf="title" maxlength="120" value="${esc(d.title)}" placeholder="${TT('к.м.н., доцент','м.ғ.к., доцент')}"></div><div class="wide"><label for="pf-spec">${TT('Специальность','Мамандығы')}</label><input id="pf-spec" data-pf="specialty" maxlength="120" value="${esc(d.specialty)}" placeholder="${TT('Терапия, кардиология','Терапия, кардиология')}"></div><div class="wide"><label for="pf-bio">${TT('О себе','Өзі туралы')}</label><textarea id="pf-bio" data-pf="bio" rows="4" maxlength="1200">${esc(d.bio)}</textarea></div></div><button class="primary" type="submit">${TT('Сохранить профиль','Профильді сақтау')}</button></form><section class="card stack"><h2>${TT('Как вас видят','Сізді қалай көреді')}</h2>${teamCard({...me,...d,role:state.role,login:SESSION.login,students:me.students||0},false)}<p class="muted small">${TT('Логин','Логин')}: ${esc(SESSION.login)} · ${esc(roleLabel(state.role))}</p></section></div>`;}
function resizePhoto(file){return new Promise((resolve,reject)=>{if(!/^image\/(jpeg|png|webp)$/.test(file.type)||file.size>15e6)return reject(Error(TT('Выберите JPEG, PNG или WebP до 15 МБ.','15 МБ дейінгі JPEG, PNG немесе WebP таңдаңыз.')));const img=new Image(),url=URL.createObjectURL(file);img.onload=()=>{const c=document.createElement('canvas');c.width=c.height=320;const s=Math.min(img.width,img.height),ctx=c.getContext('2d');ctx.drawImage(img,(img.width-s)/2,(img.height-s)/2,s,s,0,0,320,320);URL.revokeObjectURL(url);let q=.86,data=c.toDataURL('image/jpeg',q);while(data.length>170000&&q>.4){q-=.12;data=c.toDataURL('image/jpeg',q);}resolve(data);};img.onerror=()=>reject(Error(TT('Не удалось прочитать изображение.','Суретті оқу мүмкін болмады.')));img.src=url;});}
document.addEventListener('input',e=>{if(e.target.dataset?.pf&&state.profileDraft){state.profileDraft[e.target.dataset.pf]=e.target.value;state.profileDirty=true;}});
document.addEventListener('change',async e=>{if(e.target.dataset?.photo===undefined)return;const file=e.target.files?.[0],draft=state.profileDraft;if(!file||!draft||state.profilePhotoBusy)return;state.profilePhotoBusy=true;try{const photo=await resizePhoto(file);if(state.profileDraft===draft){draft.photo=photo;state.profileDirty=true;render();}}catch(err){toast(err.message)}finally{state.profilePhotoBusy=false;}});
document.addEventListener('click',e=>{const b=e.target.closest?.('button');if(b?.dataset.q==='photo-remove'&&state.profileDraft){state.profileDraft.photo='';state.profileDirty=true;render();}});
async function saveProfile(){
 if(!state.profileDraft||state.profilePhotoBusy)return false;
 const draft=state.profileDraft,snapshot=JSON.stringify(draft);
 return operation(async()=>{const r=await api('/api/profile',JSON.parse(snapshot));state.profiles=r.profiles;
  if(state.profileDraft===draft&&JSON.stringify(draft)===snapshot){state.profileDraft=null;state.profileDirty=false;}
  render();toast(TT('Профиль сохранён.','Профиль сақталды.'));
 });
}
